import{_ as e,o as s,c as i,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"Sharding","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/storage/sharding.md","filePath":"system-design/storage/sharding.md","lastUpdated":1788475713000}'),r={name:"system-design/storage/sharding.md"};function n(o,a,l,h,d,c){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="sharding" tabindex="-1">Sharding <a class="header-anchor" href="#sharding" aria-label="Permalink to &quot;Sharding&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>Sharding</strong> 把数据按某 key hash/range 分散到多台机器上, 让写入 throughput 随机器数线性扩展. 核心难关:</p><ol><li><strong>Shard Key 怎么选</strong>: 重写 index 经常 painful, 选错 hot shard。</li><li><strong>路由 mechanism</strong>: client 直知 shard 还是 coordinator 转?</li><li><strong>Rebalance 算法</strong>: 加机器 / 减机器需要 move 多少 data?</li><li><strong>Cross-shard transactions</strong>: ACID 跨 shard 难, eventual 与 2PC 之间取 trade-off.</li><li><strong>Hot shard (long-tail load)</strong>: 单 shard 60% traffic 因 celebrity / 明星 key.</li></ol><p>本章梳理 4 类主要 sharding 模式 (hash / range / directory / consistent hashing), rebalance 数据迁移代价, classic story (Instagram 2014 12-shard, Imgur unkeyed shard, Twitter tweepy snowflake hot shard) + modern automation (Vitess, Vitess, Spilo, Aurora auto-shard)。</p><hr><h2 id="一、hash-based-sharding" tabindex="-1">一、Hash-based Sharding <a class="header-anchor" href="#一、hash-based-sharding" aria-label="Permalink to &quot;一、Hash-based Sharding&quot;">​</a></h2><h3 id="算法" tabindex="-1">算法 <a class="header-anchor" href="#算法" aria-label="Permalink to &quot;算法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shard_id = hash(mod, partition_key) % N_shards</span></span></code></pre></div><p>例: <code>user_id % 1024</code>。 简单, 路由直接 calc hash, 不需 meta-store lookup。</p><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h3><ul><li>分布均匀 (假设 hash 函数好, e.g., FNV1a / MURMUR3)</li><li>路由 O(1), client 端可算</li></ul><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h3><ul><li><strong>加机器需 rehash</strong>: N 增加 → 几乎所有 keys 重新 mapping, 大 move。</li><li><strong>Range query 无效</strong>: 相邻 user_id 可能落不同 shard。</li><li><strong>Hot key 仍存在巨大单 hot shard</strong>: hop-key hashed 仍 al 热足中 shard 中 (上 fine 一 hot instance)。</li></ul><h3 id="修复-consistent-hashing" tabindex="-1">修复 (consistent hashing) <a class="header-anchor" href="#修复-consistent-hashing" aria-label="Permalink to &quot;修复 (consistent hashing)&quot;">​</a></h3><p>见后节。</p><hr><h2 id="二、range-based-sharding" tabindex="-1">二、Range-based Sharding <a class="header-anchor" href="#二、range-based-sharding" aria-label="Permalink to &quot;二、Range-based Sharding&quot;">​</a></h2><h3 id="算法-1" tabindex="-1">算法 <a class="header-anchor" href="#算法-1" aria-label="Permalink to &quot;算法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>range mapping: [(min, sh1), (a, sh2), (b, sh3), ..., (max, shN)]</span></span></code></pre></div><p>适用于<strong>按 key 顺序扫描的查询</strong>:</p><ul><li>时序数据 by timestamp range</li><li>用户 ID by alphabetical range</li><li>主键范围 scan query</li></ul><h3 id="优点-1" tabindex="-1">优点 <a class="header-anchor" href="#优点-1" aria-label="Permalink to &quot;优点&quot;">​</a></h3><ul><li><strong>范围查询高效</strong>: shards 在 同 range 内, query 落单一 shard。</li><li><strong>Rebalance 低成本</strong>: split a range × 2, half the keys migrate. Less than full rehash。</li><li><strong>自然 co-locating</strong>: 相关 keys 同 shard (e.g., 同 user_id 的所有 events)。</li></ul><h3 id="缺点-1" tabindex="-1">缺点 <a class="header-anchor" href="#缺点-1" aria-label="Permalink to &quot;缺点&quot;">​</a></h3><ul><li><strong>Hot range</strong>: 单 range (e.g., 过去 1 小时写入) 高写 traffic. recent writes 全到一个 shard。</li><li><strong>Add Shard</strong>: 切 range 的 split 影响, multiple shard keys moved 可以轻量但 cross-middle high brief 因为前缀 hot range.</li></ul><h3 id="real-example" tabindex="-1">Real Example <a class="header-anchor" href="#real-example" aria-label="Permalink to &quot;Real Example&quot;">​</a></h3><p>HBase region is by row-key range. Amazon DynamoDB Streams 同时也是. Range 说 timestamp 正好 natural range.</p><p>Spanner interleaved tables: parent + child share shard (key prefix). child placement near parent for join optimization。</p><hr><h2 id="三、directory-based-sharding" tabindex="-1">三、Directory-based Sharding <a class="header-anchor" href="#三、directory-based-sharding" aria-label="Permalink to &quot;三、Directory-based Sharding&quot;">​</a></h2><h3 id="算法-2" tabindex="-1">算法 <a class="header-anchor" href="#算法-2" aria-label="Permalink to &quot;算法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>key → lookup mapping table → shard_id</span></span></code></pre></div><p>有一 central directory service (metadata DB) 指 key 到 shard 映射. dynamic shard mapping.</p><h3 id="优点-2" tabindex="-1">优点 <a class="header-anchor" href="#优点-2" aria-label="Permalink to &quot;优点&quot;">​</a></h3><ul><li><strong>灵活</strong>: 如果某 shard 太热, 手动 split 单 key 到新 shard. update directory.</li><li><strong>Migration 灵活</strong>: 客户端不经 hash, 经 directory service, 整体栈 decoupled.</li></ul><h3 id="缺点-2" tabindex="-1">缺点 <a class="header-anchor" href="#缺点-2" aria-label="Permalink to &quot;缺点&quot;">​</a></h3><ul><li><strong>Directory service是瓶颈 + 单点风险</strong>: 所有 request 都过目录. RAID multi-replic service + cache + hot-shard rebalance for scale.</li><li><strong>High latency</strong>: 一 extra network lookup; directory cache 引入 stale risk (与 shard split timing mismatch).</li></ul><h3 id="real-example-1" tabindex="-1">Real example <a class="header-anchor" href="#real-example-1" aria-label="Permalink to &quot;Real example&quot;">​</a></h3><p>Vitess MySQL uses <strong>vtgate</strong> as a router to MySQL shards. <strong>vttablet</strong> per MySQL instance. vtgate lookup global topology in etcd.</p><p>Apache ShardingSphere, PostgreSQL 通过 Citus 提供类似 dynamic sharding.</p><hr><h2 id="四、consistent-hashing" tabindex="-1">四、Consistent Hashing <a class="header-anchor" href="#四、consistent-hashing" aria-label="Permalink to &quot;四、Consistent Hashing&quot;">​</a></h2><h3 id="算法思想" tabindex="-1">算法思想 <a class="header-anchor" href="#算法思想" aria-label="Permalink to &quot;算法思想&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>环 ring 模型:</span></span>
<span class="line"><span>   node hashes random fixed position in ring (0 ... 2^32-1)</span></span>
<span class="line"><span>   key hashes to position in same ring</span></span>
<span class="line"><span>   路由到 first node clockwise from key position</span></span></code></pre></div><p>加 new node N:</p><ul><li>仅 keys 在 (key_pos_in ring, N_pos) 选 reassign to N.</li><li>其他 keys 不变.</li></ul><p>平均 N = ring中所有 keys, 期望贡献比例 = 1/(nodes_count). 在新 node 加入, 转 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>N</mi></mrow><annotation encoding="application/x-tex">1/N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 不重.</p><h3 id="virtual-nodes-vnodes" tabindex="-1">Virtual Nodes (Vnodes) <a class="header-anchor" href="#virtual-nodes-vnodes" aria-label="Permalink to &quot;Virtual Nodes (Vnodes)&quot;">​</a></h3><p>Single hash position 可能让一些 node 拥有过 multiple 区段. 用 <strong>N virtual node per physical node</strong> 让分布更均匀:</p><ul><li>each physical node mapped to ~150 virtual positions on ring</li><li>给均匀 hash distribution</li></ul><p>Cassandra, Scylladb, Riak 默认 vnodes = 256 per physical node. Redis Cluster 沿 0-16384 hash slots.</p><h3 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to &quot;优缺点&quot;">​</a></h3><ul><li><strong>加机器 only 1/N 数据 move</strong>: 总 key 数据量 × (1/N) move. Add 10th node to 9-node cluster → 1/(=N) data = ~10% keys rehash。Perfect.</li><li><strong>Range query 仍无效</strong>: range queries cross multiple shards (no range locality)</li><li><strong>Hash ring + cache invalidation</strong>: hot shard if multiple hot keys to same virtual node — 仍然 issue。</li></ul><hr><h2 id="五、cross-shard-事务" tabindex="-1">五、Cross-shard 事务 <a class="header-anchor" href="#五、cross-shard-事务" aria-label="Permalink to &quot;五、Cross-shard 事务&quot;">​</a></h2><p>事务跨多 shards 是 distributed systems hard problem. 几种方案:</p><h3 id="two-phase-commit-2pc" tabindex="-1">Two-Phase Commit (2PC) <a class="header-anchor" href="#two-phase-commit-2pc" aria-label="Permalink to &quot;Two-Phase Commit (2PC)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Coordinator:</span></span>
<span class="line"><span>1. 联系所有 participants &quot;准备&quot;.</span></span>
<span class="line"><span>2. 各 participants hold lock + ready, ack.</span></span>
<span class="line"><span>3. Coordinator 收齐 ack → &quot;commit&quot; to all.</span></span>
<span class="line"><span>4. participants commit + release lock.</span></span></code></pre></div><ul><li>linearizable + atomic + cross-shard transactional。</li><li>但 blocking coordinator fail, lock waiting time long</li><li>取舍: latency 高; 性能不佳。</li></ul><h3 id="saga-compensating-transactions" tabindex="-1">Saga (Compensating Transactions) <a class="header-anchor" href="#saga-compensating-transactions" aria-label="Permalink to &quot;Saga (Compensating Transactions)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stage 1 (svc1): WRITE → commit.</span></span>
<span class="line"><span>Stage 2 (svc2): WRITE → commit.</span></span>
<span class="line"><span>if Stage 2 fail: emit &quot;undo Stage 1 (Compensate)&quot;.</span></span></code></pre></div><ul><li>eventual consistency</li><li>Business-level compensation</li><li>多 for distributed transactions where 2PC 不行</li></ul><h3 id="eventual-consistency-idempotent-retry" tabindex="-1">Eventual consistency + idempotent retry <a class="header-anchor" href="#eventual-consistency-idempotent-retry" aria-label="Permalink to &quot;Eventual consistency + idempotent retry&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service 1 update + emit event → topic. Service 2 consumes event + 更新 local。</span></span></code></pre></div><ul><li>High throughput, async, basicallySaga.</li><li>不 strict atomic.</li></ul><h3 id="cockroachdb-spanner-cp-atomicity-2pc-across-shards" tabindex="-1">CockroachDB / Spanner cp Atomicity 2PC across shards <a class="header-anchor" href="#cockroachdb-spanner-cp-atomicity-2pc-across-shards" aria-label="Permalink to &quot;CockroachDB / Spanner cp Atomicity 2PC across shards&quot;">​</a></h3><p>内部 2PL + Paxos replica + 2PC 跨 shard:</p><ul><li>Performance ~80ms per transaction (compared to 5ms single shard)</li><li>Strict serializable + linearizable + cross-shard ACID</li></ul><p>Trade-off is large; only used when must.</p><hr><h2 id="六、rebalance-migration" tabindex="-1">六、Rebalance &amp; Migration <a class="header-anchor" href="#六、rebalance-migration" aria-label="Permalink to &quot;六、Rebalance &amp; Migration&quot;">​</a></h2><h3 id="range-sharding-split" tabindex="-1">Range Sharding Split <a class="header-anchor" href="#range-sharding-split" aria-label="Permalink to &quot;Range Sharding Split&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shard 负载 &gt; threshold → split: shard_a takes [0, 50] shard_a_new takes [50, 100]</span></span>
<span class="line"><span>move keys [50, 100] to new shard。</span></span></code></pre></div><p>期间:</p><ul><li><strong>Dual-write</strong>: client dual-write new + old shard 期间 migration window.</li><li><strong>Read from new shard after migrate complete</strong></li></ul><h3 id="hash-sharding-rebalance" tabindex="-1">Hash Sharding Rebalance <a class="header-anchor" href="#hash-sharding-rebalance" aria-label="Permalink to &quot;Hash Sharding Rebalance&quot;">​</a></h3><p>非 consistent hashing:</p><ul><li>增 N → rehash几乎所有 keys.</li><li>多数 production hash-based sharding 用 consistent hashing 解决.</li></ul><p>consistent hashing:</p><ul><li>同 vnode count per node 加 new node reassign vnode slot.</li><li>multiple vnodes per physical node 容易 load balance.</li></ul><h3 id="coordinator-assisted-migrations-vitess" tabindex="-1">Coordinator-assisted migrations (Vitess) <a class="header-anchor" href="#coordinator-assisted-migrations-vitess" aria-label="Permalink to &quot;Coordinator-assisted migrations (Vitess)&quot;">​</a></h3><p>Vitess vreplication engine 让 migration while serving:</p><ol><li>vstream capturing changes on source. 2.Keeping vstream 同 starting point shard migration pulls.</li><li>After catch-up, swap-over write traffic.</li><li>tear down old.</li></ol><p>Migration <strong>draining binary</strong> flip client routing — full hot migration, no downtime.</p><hr><h2 id="七、hot-shard-mitigation" tabindex="-1">七、Hot Shard mitigation <a class="header-anchor" href="#七、hot-shard-mitigation" aria-label="Permalink to &quot;七、Hot Shard mitigation&quot;">​</a></h2><h3 id="read-replica" tabindex="-1">Read Replica <a class="header-anchor" href="#read-replica" aria-label="Permalink to &quot;Read Replica&quot;">​</a></h3><p>读写 hot key → 路由到多个副本分摊读流量 → 为热点 key 预留专用 replica（避免与普通流量争抢资源）。 Cassandra Naturally多个 replica. 实际流量分布 across multiple replicas + read repair。</p><h3 id="caching-hot-key-redis-local-tier" tabindex="-1">Caching Hot Key (Redis local tier) <a class="header-anchor" href="#caching-hot-key-redis-local-tier" aria-label="Permalink to &quot;Caching Hot Key (Redis local tier)&quot;">​</a></h3><p>If hot-key data fits in Redis, server-side cache each local Redis 实例 hit reduce DB load 99%.</p><h3 id="celebrity-problem-pre-compute-at-cache-layer" tabindex="-1">Celebrity Problem + Pre-compute at cache-layer <a class="header-anchor" href="#celebrity-problem-pre-compute-at-cache-layer" aria-label="Permalink to &quot;Celebrity Problem + Pre-compute at cache-layer&quot;">​</a></h3><p>Twitter 的名人发推（&quot;Kardashian 问题&quot;）是典型 fan-out 风暴：写时推送会把一条推文复制到数千万粉丝的收件箱。工程解法是<strong>混合模型</strong>：预先识别名人账号，其推文不写入粉丝 inbox，改为读时从作者 timeline 实时拉取合并——写扩散转读聚合。</p><h3 id="cache-replication" tabindex="-1">Cache Replication <a class="header-anchor" href="#cache-replication" aria-label="Permalink to &quot;Cache Replication&quot;">​</a></h3><p>Cache 多副本, local 反向 proxy cache cluster with consistent hash routing + replicate top keys to multiple caches (Caffeine + Ristretto with bloom/cuckoo hot-key replication support).</p><h3 id="multi-level-one-machine-side-cache-read-through" tabindex="-1">Multi-level One Machine Side Cache (read-through) <a class="header-anchor" href="#multi-level-one-machine-side-cache-read-through" aria-label="Permalink to &quot;Multi-level One Machine Side Cache (read-through)&quot;">​</a></h3><p>Application server in-process cache (Guava Caffeine / HashiCorp LRUdb / Ristretto) for hottest few thousand keys to shield multiple layers。</p><hr><h2 id="八、typical-case" tabindex="-1">八、typical case <a class="header-anchor" href="#八、typical-case" aria-label="Permalink to &quot;八、typical case&quot;">​</a></h2><h3 id="instagram-2014-sharding-by-user-id" tabindex="-1">Instagram 2014 Sharding by user_id <a class="header-anchor" href="#instagram-2014-sharding-by-user-id" aria-label="Permalink to &quot;Instagram 2014 Sharding by user_id&quot;">​</a></h3><p>Migration from monolithic Postgres to 12+ Postgres instances by sharding user_id hash direct keys mod 4096:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shard = user_id % 4096</span></span>
<span class="line"><span>instance = shard / (4096 / 12) // 分配每 instance 多 shard key</span></span></code></pre></div><p>purpose 选 4096 在 future scaling — 加 to 24 后 让粉 federations in half cost migration simple. cart 上 5 years after use ACTOR still 4096-shard model in Facebook 5 years 后.</p><h3 id="twitter-snowflake-user-shard" tabindex="-1">Twitter Snowflake + user_shard <a class="header-anchor" href="#twitter-snowflake-user-shard" aria-label="Permalink to &quot;Twitter Snowflake + user_shard&quot;">​</a></h3><p>Snowflake ID 是全球唯一 ID generated by:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>timestamp_ms | datacenter_id | worker_id | sequence</span></span></code></pre></div><p>Snowflake 让 social graph split 但 user_id_nés&#39; 高 hit routing + caching - 每用户数据 co-resident (covidding share) keys 食均.</p><h3 id="vitess-youtube-at-scale" tabindex="-1">Vitess - YouTube at scale <a class="header-anchor" href="#vitess-youtube-at-scale" aria-label="Permalink to &quot;Vitess - YouTube at scale&quot;">​</a></h3><p>Vitess 自 2011 开始 at YouTube. toda y open source USED by Slack, Square Cash, GitHub multim. clusters with thousands of MySQL shards. Requirements: ACID transactions at cross-shard (Vitess vstream v2 plan), migration online, etc.</p><h3 id="vitess-cross-shard-transactions" tabindex="-1">Vitess + cross-shard transactions <a class="header-anchor" href="#vitess-cross-shard-transactions" aria-label="Permalink to &quot;Vitess + cross-shard transactions&quot;">​</a></h3><p>Vitess VStream 提供 save point transaction across shards, <strong>limited semantics as 2PC per-Vitess</strong> at higher latency coin.</p><hr><h2 id="九、典型事故" tabindex="-1">九、典型事故 <a class="header-anchor" href="#九、典型事故" aria-label="Permalink to &quot;九、典型事故&quot;">​</a></h2><h3 id="shard-split-pain" tabindex="-1">Shard Split Pain <a class="header-anchor" href="#shard-split-pain" aria-label="Permalink to &quot;Shard Split Pain&quot;">​</a></h3><p>某公司 host-based shard 加 scheduler, + 基础 directory table update split ranges hot shard, 实际 后 client 健康状态 stale cache split after → look up old shard 个 fail 5 seconds. Fix: dual-cycle served while directory cache propagates.</p><h3 id="postgres-hot-table-citus" tabindex="-1">Postgres Hot Table (Citus) <a class="header-anchor" href="#postgres-hot-table-citus" aria-label="Permalink to &quot;Postgres Hot Table (Citus)&quot;">​</a></h3><p>Citus cluster with 4 nodes, one node has 70% hashes hit based on user_id.一个人用户频繁 user_id 正好分布 region shard。 Redis local cache that hot user → 修复.</p><h3 id="vitess-vstream-replication-logs-bit-drift-race" tabindex="-1">Vitess vstream replication logs bit-drift race <a class="header-anchor" href="#vitess-vstream-replication-logs-bit-drift-race" aria-label="Permalink to &quot;Vitess vstream replication logs bit-drift race&quot;">​</a></h3><p>Vitess retry-mode vcstream logic over long-table migrate pound wall causing 表 率 alerts.2018 vert spurious panic trov you. Fix batch vstream consensus.</p><hr><h2 id="十、易错清单" tabindex="-1">十、易错清单 <a class="header-anchor" href="#十、易错清单" aria-label="Permalink to &quot;十、易错清单&quot;">​</a></h2><ol><li><strong>Initial shard 第一步先 聚 集 hot-key range</strong>: 数 dynamic user. Need a factor of 4-10x margin.</li><li><strong>Hash-based range query cannot efficiently span shards</strong>: 如果 业务优先 rаngе, 选 range-based sharding 不 hash.</li><li><strong>Vnodes ≠ guaranteed 热邓小平 distribution</strong>: 即使 consistent hashing, <strong>single hot key</strong> hits one vnode, no help. Need cache + pre-compute.</li><li><strong>2PC cross-shard latency &gt; 10× single-shard</strong>: cross-shard ACID 不 should large throughput. Saga 或 eventual consistency preferred for hot path.</li><li><strong>Pre-balancing hot-key监控</strong>: 偶尔 hot 单 key surge (e.g., download/hot news) 提 前见 re-route critical.</li><li><strong>Migration always dual-write during transition</strong>: dual-caching key avoidance keeps safe availability.</li><li><strong>Shard key must not change</strong>: if sharding key changes, row must re-homes.</li><li><strong>PostgreSQL primary key after split-over</strong>: UNIVERSE has 棋 consensus key per table shards 平台 multi-tenant ideal first place.</li></ol><hr><h2 id="十一、这一章带走的东西" tabindex="-1">十一、这一章带走的东西 <a class="header-anchor" href="#十一、这一章带走的东西" aria-label="Permalink to &quot;十一、这一章带走的东西&quot;">​</a></h2><ol><li>Sharding 方式: hash O(1) 路由 + 写均匀但 range queries 无; range 自然 range + 子查询 efficient 但 hot 集中; directory-like metadata locator.</li><li>Consistent hashing 加 node 仅 1/N 数据迁移: 适合 dynamic cluster size.</li><li>Hot shard mitigation: pre-cache + 完美 celebrity special handling + multi-tier cache Layer.</li><li>Cross-shard transaction: 2PC 严哥latency 80ms+; Saga / eventual consistency 是 scalable path.</li><li>Migration <strong>dual-write + read from new + final swap</strong>, downtime free.</li><li>Practical: Instagram foreshadowed 4096-shard hash, well designed scalable without bottleneck 斚 10 years.</li></ol><hr><p>下一节 → <a href="./../cache/">缓存</a></p>`,127)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
